const upsertRongCloudSystemConfig = `-- name: UpsertRongCloudSystemConfig :one

INSERT INTO rongcloud_system_config (workspace_id, config_key, node_id, config, config_version)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (workspace_id, config_key) DO UPDATE SET
    node_id = EXCLUDED.node_id,
    config = EXCLUDED.config,
    config_version = EXCLUDED.config_version,
    updated_at = now()
RETURNING id, workspace_id, config_key, node_id, config, config_version, created_at, updated_at
`

type UpsertRongCloudSystemConfigParams struct {
	WorkspaceID   pgtype.UUID `json:"workspace_id"`
	ConfigKey     string      `json:"config_key"`
	NodeID        pgtype.UUID `json:"node_id"`
	Config        []byte      `json:"config"`
	ConfigVersion int32       `json:"config_version"`
}

